   "lead": "Nell'ambito dell'Inspiration Tour, l'amministratore della Nasa Jared Isaacman pilota uno dei tre caccia F-5 che sorvoleranno lo stadio MetLife di East Rutherford, nel New Jersey, per aprire la partita tra New York Jets e Cleveland Browns di domenica 11 ottobre. Membri del team dell'agenzia incontreranno anche i tifosi. Lo riferisce la Nasa.",
