   "orig": "Cosmic House of Mirrors",
   "lead": "Una nuova immagine del telescopio spaziale James Webb, diffusa dalla Nasa il 29 settembre 2026, mostra galassie deformate e moltiplicate come in una casa degli specchi. Le galassie dorate fanno parte dell'ammasso MACS J0454.1-0300, mentre altre galassie arancioni risultano raggruppate poco distante. L'effetto di specchi deriva dalla deformazione delle immagini visibili nel campo. Lo riferisce la Nasa.",
