   "lead": "In Gambia i tribunali di revisione stanno esaminando le contestazioni alle iscrizioni nelle liste elettorali. A Kanifing la magistrata Isatou Sallah-M'Bai ha respinto l'obiezione di Binta Nyabally contro l'iscrizione di Mariama Jallow, che resta nel registro. A Brusubi un'altra obiezione, contro Maimuna Camara, è stata respinta perché chi la sollevava non ha fornito prove sufficienti.",
