   "lead": "Nella Giornata mondiale della salute mentale l'ANSA riporta che almeno 8 milioni di italiani hanno problemi di salute mentale, dall'ansia ai disturbi più gravi, ma i servizi pubblici ne hanno seguiti nel 2024 circa 845mila. Rai News segnala che i casi nel mondo sono raddoppiati dal 1990 al 2023, soprattutto fra i giovani.",
